package com.vandorlabs.neoforge.builders;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.world.item.ItemStack;
public final class NativeBuilderData {
 public static CompoundTag save(ItemStack[] items,HolderLookup.Provider registries){var tag=new CompoundTag();var list=new ListTag();for(int slot=0;slot<items.length;slot++)if(!items[slot].isEmpty()){var entry=new CompoundTag();entry.putInt("Slot",slot);entry.put("Stack",items[slot].save(registries));list.add(entry);}tag.put("Items",list);return tag;}
 public static ItemStack[] read(CompoundTag tag,HolderLookup.Provider registries){return read(tag,registries,"synthesis_tower");}
 public static ItemStack[] read(CompoundTag tag,HolderLookup.Provider registries,String machine){return read(tag,registries,machine,false);}
 public static ItemStack[] read(CompoundTag tag,HolderLookup.Provider registries,String machine,boolean digitizing){
  if(!tag.getAllKeys().stream().allMatch(k->k.equals("Items")))throw new IllegalArgumentException("Builder inventory fields");var items=new ItemStack[7];java.util.Arrays.fill(items,ItemStack.EMPTY);if(!tag.contains("Items"))return items;
  if(!(tag.get("Items") instanceof ListTag list)||!list.isEmpty()&&list.getElementType()!=Tag.TAG_COMPOUND||list.size()>7)throw new IllegalArgumentException("Builder inventory schema");boolean[] seen=new boolean[7];
  for(var value:list){var entry=(CompoundTag)value;if(!entry.getAllKeys().equals(java.util.Set.of("Slot","Stack"))||!entry.contains("Slot",Tag.TAG_INT)||!entry.contains("Stack",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Builder inventory entry");int slot=entry.getInt("Slot");if(slot<0||slot>6||seen[slot])throw new IllegalArgumentException("Builder inventory slot");seen[slot]=true;var encoded=entry.getCompound("Stack");var stack=ItemStack.parse(registries,encoded).orElseThrow(()->new IllegalArgumentException("Builder inventory item"));if(stack.isEmpty()||stack.getCount()<1||stack.getCount()>stack.getMaxStackSize()||slot>=2&&stack.getCount()!=1||!encoded.equals(stack.save(registries)))throw new IllegalArgumentException("Builder inventory count/components");String id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();if(slot==0&&!(digitizing?machine.equals("synthesis_tower")&&stack.getCount()==1&&NativeBlockRecipeData.eligible(stack):id.equals("vandorlabs:"+com.vandorlabs.machines.BuilderRecipeCatalog.input(machine)))||slot==1&&!(NativeBuilderProducts.output(machine,id)||machine.equals("synthesis_tower")&&stack.getCount()==1&&NativeBlockRecipeData.eligible(stack))||(slot==2||slot>=4)&&!com.vandorlabs.neoforge.rack.NativeBatteryModule.valid(stack)||slot==3&&!com.vandorlabs.neoforge.credentials.NativeCredentialItems.accepts(stack,true))throw new IllegalArgumentException("Builder inventory slot item");items[slot]=stack;}
  return items;
 }
 /** Only vanilla storage hints and the absent default cosmetic counter are interchangeable. Ownership/settings stay exact. */
 public static CompoundTag normalizedSnapshot(CompoundTag original){var tag=original.copy();if(tag.contains("keepPacked",Tag.TAG_BYTE)&&tag.getByte("keepPacked")==0)tag.remove("keepPacked");if(tag.contains("NeoForgeData",Tag.TAG_COMPOUND)&&tag.getCompound("NeoForgeData").isEmpty())tag.remove("NeoForgeData");if(tag.contains("BatterySequences",Tag.TAG_LONG_ARRAY)){long[] sequences=tag.getLongArray("BatterySequences");if(sequences.length==4&&sequences[0]==0&&sequences[1]==0&&sequences[2]==0&&sequences[3]==0)tag.remove("BatterySequences");}if(tag.contains("Synthesis",Tag.TAG_COMPOUND)){var work=tag.getCompound("Synthesis");if(work.contains("Mode",Tag.TAG_INT)&&work.getInt("Mode")==0)work.remove("Mode");}return tag;}
 public static boolean sameSnapshots(CompoundTag a,CompoundTag b){return java.util.Objects.equals(a,b)||a!=null&&b!=null&&normalizedSnapshot(a).equals(normalizedSnapshot(b));}
 private NativeBuilderData(){}
}
